import{_ as s,a as e,c as i,ac as t}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"数据库基础与选型","description":"比较关系、文档、宽列、键值、图和时序模型的职责、使用边界与学习入口。","frontmatter":{"title":"数据库基础","description":"数据库","sources":[{"repository":"jekyall_blog","file":"_posts/DataStorage/DataOther.md","date":"Sun May 07 2023 13:48:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"storage","title":"存储基础与历史资料","link":"/topics/storage/"},{"id":"fundamentals","title":"操作系统原理","link":"/topics/fundamentals/"},{"id":"mysql","title":"MySQL","link":"/topics/mysql/"},{"id":"postgres","title":"PostgreSQL","link":"/topics/postgres/"},{"id":"redis","title":"Redis","link":"/topics/redis/"},{"id":"mongodb","title":"MongoDB","link":"/topics/mongodb/"}],"kind":"参考资料","scope":"general","audience":"general","group":"数据库与存储","summary":"比较关系、文档、宽列、键值、图和时序模型的职责、使用边界与学习入口。","status":"active","related":[{"title":"数据库系统原理（04735）","link":"/middleware/storage-foundations/storage/plus/middleware-subjects/databases","kind":"专题笔记","scope":"general","audience":"general"},{"title":"数据库系统原理（04735） · 数据库编程：过程、函数与游标至参考与延伸","link":"/middleware/storage-foundations/storage/plus/middleware-subjects/databases-part-02","kind":"专题笔记","scope":"general","audience":"general"},{"title":"数据库系统原理（04735） · 数据库系统与三级模式至SQL、索引与视图的职责","link":"/middleware/storage-foundations/storage/plus/middleware-subjects/databases-part-01","kind":"专题笔记","scope":"general","audience":"general"},{"title":"Redis：数据结构服务、缓存与部署边界","link":"/middleware/redis/foundations","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis：数据结构服务、缓存与部署边界 · 缓存异常至延伸阅读","link":"/middleware/redis/foundations-part-03","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":false,"next":{"text":"数据库系统原理（04735）","link":"/middleware/storage-foundations/storage/plus/middleware-subjects/databases"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"数据库系统原理（04735）","link":"/middleware/storage-foundations/storage/plus/middleware-subjects/databases"}},"headers":[],"relativePath":"middleware/storage-foundations/storage/plus/subjects/dataother.md","filePath":"middleware/storage-foundations/storage/plus/subjects/dataother.md"}'),n={name:"middleware/storage-foundations/storage/plus/subjects/dataother.md"};function d(l,a,r,p,h,o){return e(),i("div",null,[...a[0]||(a[0]=[t(`<p><span id="数据库基础" aria-hidden="true"></span></p><h1 id="数据库基础-从数据模型到选型" tabindex="-1">数据库基础：从数据模型到选型 <a class="header-anchor" href="#数据库基础-从数据模型到选型" aria-label="Permalink to &quot;数据库基础：从数据模型到选型&quot;">​</a></h1><p>先看数据关系与访问方式，再选择存储产品。这里比较职责和入门路径，不为每个产品重复一套“安装、建表、增删改查”。</p><p><span id="服务端开发需要了解哪些数据库" aria-hidden="true"></span><span id="数据库分类" aria-hidden="true"></span></p><h2 id="requirements" tabindex="-1">先明确要解决的问题 <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;先明确要解决的问题 {#requirements}&quot;">​</a></h2><ol><li>数据如何关联：表之间的约束、文档聚合、键值访问，还是图遍历？</li><li>主要工作负载：事务写入、按键读取、范围扫描、统计分析或时间窗口聚合？</li><li>能接受什么故障：短暂旧值、丢失窗口、恢复时间与跨节点一致性分别是多少？</li><li>如何运维：数据量、热点、扩展方式、备份恢复及团队已有经验？</li></ol><p>“关系型”“内存”“分布式”不是互斥分类：前者是数据模型，内存描述存放与访问方式，分布式描述部署与协调方式。Redis 可同时属于键值存储与内存数据系统。</p><h2 id="models" tabindex="-1">按数据模型区分职责 <a class="header-anchor" href="#models" aria-label="Permalink to &quot;按数据模型区分职责 {#models}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>常见用途</th><th>需要先确认的边界</th></tr></thead><tbody><tr><td>关系模型</td><td>有关联与事务约束的业务记录</td><td>表设计、事务、索引和查询计划</td></tr><tr><td>文档模型</td><td>以聚合文档为单位的读写</td><td>文档边界、嵌套增长、跨文档更新</td></tr><tr><td>键值及集合</td><td>缓存、会话、计数、排序集合</td><td>过期、淘汰、持久化、热点</td></tr><tr><td>宽列模型</td><td>围绕分区键的大规模已知查询</td><td>按查询设计表、分区大小与一致性设置</td></tr><tr><td>图模型</td><td>多跳关系、路径与邻居查询</td><td>遍历深度、边规模和查询代价</td></tr><tr><td>时间序列</td><td>按时间写入、窗口聚合与保留</td><td>标签基数、采样、压缩与保留策略</td></tr></tbody></table><p>NoSQL 是一组不同模型的统称，不意味着所有产品都没有事务，也不意味着表模型天然不能扩展。不能只凭一个分类判断系统能力。</p><p><span id="关系型数据库-sql" aria-hidden="true"></span><span id="mysql" aria-hidden="true"></span><span id="以下是-mysql-的基础知识" aria-hidden="true"></span><span id="以下是-mysql-的一些基本命令语句" aria-hidden="true"></span><span id="oracle" aria-hidden="true"></span><span id="oracle-介绍" aria-hidden="true"></span><span id="oracle-基本命令语句" aria-hidden="true"></span><span id="postgresql" aria-hidden="true"></span></p><h2 id="relational" tabindex="-1">关系型数据库：MySQL、PostgreSQL 与 Oracle <a class="header-anchor" href="#relational" aria-label="Permalink to &quot;关系型数据库：MySQL、PostgreSQL 与 Oracle {#relational}&quot;">​</a></h2><h3 id="共通学习顺序" tabindex="-1">共通学习顺序 <a class="header-anchor" href="#共通学习顺序" aria-label="Permalink to &quot;共通学习顺序&quot;">​</a></h3><p>建模与约束 → 基本查询 → 连接与聚合 → 事务与隔离 → 索引与执行计划 → 备份恢复。SQL 基础可以迁移，但类型、分页、函数、账号与存储程序语法有产品差异。</p><table tabindex="0"><thead><tr><th>产品</th><th>先掌握的入口</th><th>不应直接照搬的内容</th></tr></thead><tbody><tr><td>MySQL</td><td><code>mysql</code> 客户端、表结构、事务引擎与 <code>EXPLAIN</code></td><td>MySQL 的 <code>LIMIT</code>、客户端 <code>DELIMITER</code></td></tr><tr><td>PostgreSQL</td><td><code>psql</code>、schema、事务与查询计划</td><td>类型、函数/过程及服务端编程语言</td></tr><tr><td>Oracle Database</td><td>SQL*Plus/SQL Developer、schema、SQL 与 PL/SQL</td><td><code>VARCHAR2</code>、序列/身份列、分页与过程调用</td></tr></tbody></table><p>Oracle 不使用 MySQL 的 <code>LIMIT</code>。SQL 中给参数取名时应与列区分，避免出现 <code>WHERE employee_id = employee_id</code> 这类没有按传入 ID 筛选的条件。</p><h3 id="连接后先验证目标" tabindex="-1">连接后先验证目标 <a class="header-anchor" href="#连接后先验证目标" aria-label="Permalink to &quot;连接后先验证目标&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3306</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> study_user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">psql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> study_db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> study_user</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlplus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> study_user@study_service</span></span></code></pre></div><p>密码通过交互或既定凭据管理流程提供。进入后确认实例、数据库/schema、账号及版本，再执行练习；客户端安装不等于服务端已初始化。</p><ul><li><a href="/middleware/mysql/base/basic/day1-7">MySQL 系统学习</a></li><li><a href="/middleware/mysql/plus/subjects/mysql-select-base">查询、聚合与函数</a></li><li><a href="/middleware/storage-foundations/storage/plus/middleware-subjects/databases">数据库模型、规范化与事务原理</a></li><li><a href="/topics/postgres/">PostgreSQL 专题</a></li></ul><p><span id="非关系型数据库-nosql-数据库" aria-hidden="true"></span><span id="mongodb" aria-hidden="true"></span><span id="cassandra" aria-hidden="true"></span></p><h2 id="document-and-wide-column" tabindex="-1">文档与宽列：MongoDB、Cassandra <a class="header-anchor" href="#document-and-wide-column" aria-label="Permalink to &quot;文档与宽列：MongoDB、Cassandra {#document-and-wide-column}&quot;">​</a></h2><h3 id="mongodb-按文档聚合业务数据" tabindex="-1">MongoDB：按文档聚合业务数据 <a class="header-anchor" href="#mongodb-按文档聚合业务数据" aria-label="Permalink to &quot;MongoDB：按文档聚合业务数据&quot;">​</a></h3><p>集合保存 BSON 文档。先决定哪些字段随对象一起读取和更新，再决定嵌入还是引用；“结构灵活”不等于无需约束、索引或迁移设计。</p><p>在已连接的 shell 中，<code>use study_db</code> 只是切换数据库上下文，数据库通常在真正写入数据后建立。不要把旧 <code>mongo</code> shell 的安装与登录命令当成所有版本通用入口。</p><div class="language-javascript vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">use study_db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db.users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">insertOne</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Lin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, age: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db.users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Lin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db.users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">updateOne</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Lin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, {$set: {age: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">26</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db.users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createIndex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({name: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>使用固定名字筛选仅用于小型练习，业务更新需使用能唯一标识目标的条件。更多内容见 <a href="/topics/mongodb/">MongoDB 专题</a>。</p><h3 id="cassandra-先定查询-再定分区键" tabindex="-1">Cassandra：先定查询，再定分区键 <a class="header-anchor" href="#cassandra-先定查询-再定分区键" aria-label="Permalink to &quot;Cassandra：先定查询，再定分区键&quot;">​</a></h3><p>表结构围绕读写路径设计。分区键决定数据放置及常见访问边界，聚簇列决定分区内排序；不能把关系数据库中任意列过滤和更新的习惯直接套进 CQL。</p><p>原笔记 <code>id uuid PRIMARY KEY</code> 的表，用 <code>WHERE name = ...</code> 更新或删除并不满足主键条件。应记录写入的 ID，再按该 ID 操作，而不是靠补一个索引就假定所有修改都成立。</p><p>需要进一步动手时，先在隔离环境确定拓扑和复制策略；单机示例 <code>replication_factor: 1</code> 不能直接当作生产高可用部署。</p><p><span id="redis" aria-hidden="true"></span></p><h2 id="cache" tabindex="-1">内存缓存：Redis 与 Memcached <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;内存缓存：Redis 与 Memcached {#cache}&quot;">​</a></h2><h3 id="redis-选择数据结构并定义可靠性" tabindex="-1">Redis：选择数据结构并定义可靠性 <a class="header-anchor" href="#redis-选择数据结构并定义可靠性" aria-label="Permalink to &quot;Redis：选择数据结构并定义可靠性&quot;">​</a></h3><p>String、Hash、List、Set、Sorted Set 分别服务不同访问方式；还要确定 TTL、内存淘汰、持久化和故障转移。主从、Sentinel 与 Cluster 解决的问题不同，不能统称“开集群就不丢数据”。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET study:token sample EX 60</span></span>
<span class="line"><span>GET study:token</span></span>
<span class="line"><span>HSET study:user:1 name Lin age 25</span></span>
<span class="line"><span>HGET study:user:1 name</span></span>
<span class="line"><span>ZADD study:rank 100 player-1 90 player-2</span></span>
<span class="line"><span>ZRANGE study:rank 0 -1 WITHSCORES</span></span></code></pre></div><p>完整类型、复制和缓存异常统一见 <a href="/middleware/redis/pro/interview/redis-面试">Redis 知识复盘</a>。</p><h3 id="memcached-简单对象缓存与失效" tabindex="-1">Memcached：简单对象缓存与失效 <a class="header-anchor" href="#memcached-简单对象缓存与失效" aria-label="Permalink to &quot;Memcached：简单对象缓存与失效&quot;">​</a></h3><p>先定义 key、序列化和过期策略。缓存可能失效或被淘汰，应用必须能正确回源；不要把它作为唯一数据来源。</p><p>下面是已经连接到隔离实例后发送的文本协议，<code>3</code> 表示值 <code>abc</code> 的字节数，不是字符数量参数占位符：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set study:example 0 60 3</span></span>
<span class="line"><span>abc</span></span>
<span class="line"><span>get study:example</span></span>
<span class="line"><span>touch study:example 120</span></span>
<span class="line"><span>delete study:example</span></span>
<span class="line"><span>stats</span></span></code></pre></div><p>客户端通常负责连接池、协议编码和错误处理，真实业务不应依赖手工 telnet 输入。</p><h2 id="specialized" tabindex="-1">图与时间序列：由查询形状决定 <a class="header-anchor" href="#specialized" aria-label="Permalink to &quot;图与时间序列：由查询形状决定 {#specialized}&quot;">​</a></h2><p>社交邻居、关系路径等多跳查询可评估图数据库，例如 Neo4j、ArangoDB；监控、传感器等按时间追加和聚合的数据可评估时间序列系统，例如 InfluxDB、OpenTSDB。产品名称只作为原笔记中的模型例子，不代表一份当前产品排名。</p><p>先用代表性数据和查询做验证：路径查询是否可限制深度？时间序列标签是否导致高基数？保留与降采样策略能否满足业务查询？不要只比较插入速度。</p><h2 id="evaluation" tabindex="-1">用一个业务场景验收选型 <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;用一个业务场景验收选型 {#evaluation}&quot;">​</a></h2><p>以订单服务为例：订单、支付与约束由权威业务存储维护，缓存只保存可重建的读模型，监控指标进入适合的时间序列系统。是否拆出这些组件，要由实际需求与运行成本决定。</p><p>比较方案时记录同一组条件：数据规模、查询分布、延迟分位数、并发写入、故障与恢复过程、容量成本。评估结果比“某数据库功能更强大”更有参考价值。</p>`,48)])])}const u=s(n,[["render",d]]);export{k as __pageData,u as default};
